diff --git a/packages/logging/src/redact.ts b/packages/logging/src/redact.ts
--- a/packages/logging/src/redact.ts
+++ b/packages/logging/src/redact.ts
@@ -1,6 +1,10 @@
 import type { Logger } from "./logger";

 const SECRET_PATTERN = /token=[^&]+/g;
+
+export function redactQueryTokens(value: string): string {
+  return value.replace(SECRET_PATTERN, "token=[redacted]");
+}

 export function redactDsn(value: string): string {
   return value.replace(/\/\/[^@]+@/, "//[redacted]@");
diff --git a/packages/api/src/routes/health.ts b/packages/api/src/routes/health.ts
--- a/packages/api/src/routes/health.ts
+++ b/packages/api/src/routes/health.ts
@@ -1,6 +1,16 @@
 import { json } from "../responses";
 import type { Route } from "../types";

+const STARTED_AT = Date.now();
+
+export function healthRoute(): Route {
+  return {
+    method: "GET",
+    path: "/api/health",
+    handler: () => json({ ok: true, uptimeMs: Date.now() - STARTED_AT }),
+  };
+}
+
 export function routes(): Route[] {
-  return [];
+  return [healthRoute()];
 }
